<template><section class="login-page"><div class="login-art"><div class="brand light-brand"><span class="brand-mark">鲜</span><span><b>鲜选</b><small>FRESH SELECT</small></span></div><div class="login-hero"><span class="eyebrow">WELCOME TO FRESH SELECT</span><h1>新鲜，<br/><i>即刻到家。</i></h1><p>每天为你精选新鲜好物，<br/>让好生活从一餐开始。</p><div class="login-fruits">🍎　🥬　🍊</div></div></div><div class="login-panel"><router-link to="/home" class="back">← 返回商城</router-link><div class="login-card"><span class="eyebrow">MEMBER LOGIN</span><h2>欢迎回来</h2><p>登录后享受会员专属权益</p><label>账号 / 手机号</label><input v-model="account" placeholder="请输入账号或手机号"/><label>密码</label><input v-model="password" type="password" placeholder="请输入密码" @keyup.enter="login"/><div class="login-options"><label><input type="checkbox" checked/> 记住我</label><a>忘记密码？</a></div><button class="primary full" @click="login">登录鲜选</button><div class="divider"><span>或</span></div><button class="wechat" @click="login">◉　微信一键登录</button><p class="register">还没有账号？ <b @click="register">立即注册</b></p><small class="demo">普通用户：任意账号　管理员演示：admin2026 / 123456</small><p v-if="error" class="login-error">{{ error }}</p></div></div></section></template>
<script setup>
import { ref, inject } from 'vue'
import { useRouter } from 'vue-router'
const account=ref(''), password=ref(''), error=ref(''), router=useRouter(), notify=inject('notify')
const createToken=(role)=>{const payload={sub:account.value||'demo',role,exp:Date.now()+30*60*1000};return btoa(JSON.stringify(payload)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}
const login=()=>{error.value='';if(!account.value||!password.value){error.value='请输入账号和密码';return}if(password.value!=='123456'){error.value='演示密码为 123456';return}const role=account.value.toLowerCase()==='admin2026'?'admin':'user';const token=createToken(role);sessionStorage.setItem('fresh_token',token);sessionStorage.setItem('fresh_role',role);if(role==='admin'){window.location.href=`${window.location.origin}/admin.html?token=${encodeURIComponent(token)}&role=admin`}else{notify('登录成功');router.push('/home')}}
const register=()=>{account.value='newuser';password.value='123456';notify('已填充演示注册账号，请点击登录')}
</script>
